WITH rollup_totals AS (SELECT dim.device, src.page, COUNT(*) AS cnt, ROUND(SUM(src.duration_sec), 2) AS total_duration_sec, GROUPING_ID() AS level_id FROM web_events src JOIN sessions dim ON src.session_id = dim.id GROUP BY CUBE (dim.device, src.page)) SELECT device, cnt, total_duration_sec, level_id, CASE WHEN device RLIKE '^(mobile|tablet)$' THEN 'OTHER_ZONE' ELSE 'PRIORITY' END AS device_zone FROM rollup_totals ORDER BY device_zone NULLS LAST;
